import{_ as o,o as a,c as e,ai as r}from"./chunks/framework.scx6l_IK.js";const c=JSON.parse('{"title":"自性","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-自性.md","filePath":"50-概念资料/dict-自性.md","lastUpdated":1778333830000}'),d={name:"50-概念资料/dict-自性.md"};function l(u,t,q,i,h,n){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="自性" tabindex="-1">自性 <a class="header-anchor" href="#自性" aria-label="Permalink to &quot;自性&quot;">​</a></h1><blockquote><p>传统：佛家 | 道家对应：道/自然 | 儒家对应：本性/天命之谓性</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>自性（梵语 Svabhāva）指众生本具的清净佛性，即&quot;本来面目&quot;。了空居士的解释非常直白：<strong>不思善不思恶时，那个最清净客观的心态，就是自性现前的状态。</strong></p><blockquote><p>&quot;菩提自性，本自清净，但用此心，直了成佛。&quot;（引六祖语）</p></blockquote><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p><strong>&quot;如来的清净法身，所有如来的清净法身就是我们的自性。十方诸佛的清净法身和我们的自性是不二的。&quot;</strong></p><p>— 第五分如理实见分</p></blockquote><blockquote><p><strong>&quot;自性其实没有奥妙的，明心见性就是明白你的真心，见到你的本性。人的本性本来就是没有特别的善，也没有特别的恶。以这种清净心来看问题，这个状态其实就是明心见性的状态。&quot;</strong></p><p>— 答疑2021-不怕念起只怕觉迟</p></blockquote><blockquote><p><strong>&quot;不思善不思恶，正与么时，那个是明上座的本来面目&quot;</strong>——你的心没有带着任何成见的时候，那个状态就是佛性显现的时候。</p><p>— 第五分如理实见分（引六祖语）</p></blockquote><blockquote><p><strong>&quot;菩提本自性，起心即是妄；在妄中，但正无三障。&quot;</strong>——&quot;但正&quot;就是心正了，没有贪嗔痴慢疑，用清净的心去面对一切，不是说什么事情都不想。</p><p>— 第五分如理实见分（引六祖语）</p></blockquote><h2 id="了空居士的独特诠释" tabindex="-1">了空居士的独特诠释 <a class="header-anchor" href="#了空居士的独特诠释" aria-label="Permalink to &quot;了空居士的独特诠释&quot;">​</a></h2><p>传统上自性常被理解为某种&quot;本体&quot;或&quot;终极存在&quot;，了空居士更强调<strong>平常化、当下化</strong>：</p><ol><li><strong>自性不在远处，就在你当下的清净心</strong>——不是要修出什么特殊境界，而是回到最平常、最客观的心态</li><li><strong>自性不是无念，是无住</strong>——不是没有念头，而是念头来了不执着、不粘着</li><li><strong>自性显现 = 清净心现前</strong>——了空居士将&quot;自性&quot;与&quot;清净心&quot;直接等同，破除神秘感</li></ol><h3 id="自性的两面" tabindex="-1">自性的两面 <a class="header-anchor" href="#自性的两面" aria-label="Permalink to &quot;自性的两面&quot;">​</a></h3><p>了空居士体系中的&quot;自性&quot;实际上有两种用法，需要区分：</p><table tabindex="0"><thead><tr><th>层面</th><th>含义</th><th>对应</th></tr></thead><tbody><tr><td><strong>体</strong></td><td>众生本具的佛性——&quot;菩提自性，本自清净&quot;</td><td>六祖&quot;本来面目&quot;</td></tr><tr><td><strong>用</strong></td><td>自性现前的状态——&quot;以清净心去看待一切&quot;</td><td>日常清净心</td></tr></tbody></table><blockquote><p>这两者是一体两面：体是性，用是心。了空居士更强调&quot;用&quot;的一面——你能以清净心面对事物，就是自性在起作用。</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>自性是很玄妙、很难证的东西</td><td>了空居士说&quot;自性其实没有奥妙&quot;——清净心就是自性现前</td></tr><tr><td>见自性=什么念头都没有</td><td>见自性是不住念头，不是没有念头——&quot;外离相，内不乱&quot;</td></tr><tr><td>自性是个人的&quot;灵魂&quot;或&quot;自我&quot;</td><td>自性是无我的——&quot;了无自性&quot;说的是一切法没有固定不变的自体</td></tr><tr><td>证悟自性后就一劳永逸</td><td>了空居士强调功夫是&quot;绵绵密密&quot;——见性后还要保任</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>异同</th></tr></thead><tbody><tr><td>佛家自性</td><td>如来藏、佛性、法身</td><td>了空居士将自性等同于清净法身——&quot;诸佛清净法身就是我们的自性&quot;</td></tr><tr><td>道家</td><td>道、自然</td><td>道家&quot;道法自然&quot;——自性也是自然如此，不是造作出来的</td></tr><tr><td>儒家</td><td>天命之谓性、本性</td><td>&quot;人之初，性本善&quot;——了空居士说&quot;不是善也不是恶，是清净&quot;</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-清净心">清净心</a> — 自性现前的状态就是清净心</li><li><a href="/50-概念资料/dict-菩提">菩提</a> — &quot;菩提自性&quot;——觉悟与自性一体</li><li><a href="/50-概念资料/dict-般若">般若</a> — 自性起用的智慧</li><li><a href="/50-概念资料/dict-顽空">顽空</a> — 执空不是自性——&quot;外不着相，内不着空&quot;</li><li><a href="/50-概念资料/dict-不二">不二</a> — 自性与万法不二</li><li><a href="/50-概念资料/dict-我执">我执</a> — 我执遮蔽自性</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 自性起用的方式——&quot;应无所住而生其心&quot;</li><li><a href="/10-核心模型/model-清净心">清净心</a> — 自性的日常表现</li><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 自性与天地万物一体</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不必将&quot;见自性&quot;看作遥不可及的目标——当下的一念清净，就是自性在起作用</li><li>&quot;不思善不思恶&quot;的练习：面对事情时，先放下&quot;好/坏&quot;的判断，以客观心看待</li><li>了空居士说&quot;外离相，内不乱&quot;——不是排除念头，是念头来了不粘着</li><li>功夫是&quot;绵绵密密&quot;——不是一悟永悟，是持续保任</li></ul><hr><blockquote><p>创建日期：2026-05-09 | 素材来源：第五分如理实见分、答疑2021-不怕念起只怕觉迟、金刚经第三分/第十分/第三十一分、定慧等持 | 观点分析及分类归纳由笔者完成</p></blockquote>',29)])])}const b=o(d,[["render",l]]);export{c as __pageData,b as default};
